contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(c.tokenBalance(address(this)) == 0);

        bool revertedPaid;
        try c.airDrop{value: amount}() { revertedPaid = false; } catch { revertedPaid = true; }
        uint balAfterPaid = c.tokenBalance(address(this));
        uint ethLeft = address(c).balance;

        c.airDrop();
        uint balAfterFree = c.tokenBalance(address(this));

        assert(revertedPaid && balAfterPaid == 0 && ethLeft == 0 && balAfterFree == 20);
    }

    fallback(bytes calldata) external returns (bytes memory) {
        return abi.encodePacked(keccak256(abi.encodePacked("Nu Token")));
    }

    receive() external payable {}
}

