    }
    receive() external payable {}
    function run() public {
        // First call: msg.sender has zero balance, supportsToken matches -> should succeed
        bool reverted1;
        try c.airDrop() { reverted1 = false; } catch { reverted1 = true; }
        uint balAfterFirst = c.tokenBalance(address(this));
